const before = wb.getRange('A6:AQ20').getValues();
const r = wb.getRange('F3:AJ3');
const n = 31;
const f:any[] = [];
const col = (i:number)=>{let s='';i++;while(i>0){const m=(i-1)%26;s=String.fromCharCode(65+m)+s;i=(i-m-1)/26;}return s;};
for(let i=0;i<n;i++) f.push(`=TEXT(${col(5+i)}4,"DDD")`);
r.setValues([f]);
const after = wb.getRange('A6:AQ20').getValues();
const diffs:any[]=[];
before.forEach((row:any[],y:number)=>row.forEach((v:any,x:number)=>{ if(v!==after[y][x]) diffs.push([col(x)+(6+y),v,after[y][x]]);}));
log('changed outside', JSON.stringify(diffs));
log(JSON.stringify(wb.getRange('F3:AJ3').getValues()[0]));
log(JSON.stringify(wb.getRange('F3:AJ3').getFormulas()[0].filter((_:any,i:number)=>i==0||i==30)));
log(JSON.stringify(wb.getRange('F4:AJ4').getValues()[0]));
log(JSON.stringify(wb.getRange('F4:AJ4').getTexts()[0]));
log(await wb.evaluate('=INDEX({"Sun","Mon","Tue","Wed","Thu","Fri","Sat"},WEEKDAY(F4))&"|"&INDEX({"Sun","Mon","Tue","Wed","Thu","Fri","Sat"},WEEKDAY(AJ4))&"|"&INDEX({"Sun","Mon","Tue","Wed","Thu","Fri","Sat"},WEEKDAY(R4))'));
wb.getRange('F3:AJ3')

